"In-house installer labor","cost_type":"LABOR","parent_code":"LAB","role_hint":"DIRECT_LABOR_COST"},{"code":"WAR","name":"Callbacks and claims","cost_type":"OTHER","parent_code":null,"role_hint":"WARRANTY_COST"},{"code":"WAR-CB","name":"Callback labor","cost_type":"SUBCONTRACTOR","parent_code":"WAR","role_hint":"WARRANTY_COST"},{"code":"WAR-CLM","name":"Claim replacement material","cost_type":"MATERIALS","parent_code":"WAR","role_hint":"WARRANTY_COST"},{"code":"OTH","name":"Other order costs","cost_type":"OTHER","parent_code":null,"role_hint":"OTHER_JOB_COST"},{"code":"OTH-DEL","name":"Delivery to site","cost_type":"OTHER","parent_code":"OTH","role_hint":"FREIGHT_COST"},{"code":"OTH-DUMP","name":"Dump fees","cost_type":"OTHER","parent_code":"OTH","role_hint":"OTHER_JOB_COST"}],"field_defs":[{"object_type":"project","job_type_key":null,"field_key":"customer_reference","label":"Customer PO or reference","data_type":"text","options":null,"required":false,"promote":false},{"object_type":"selection","job_type_key":null,"field_key":"style_color","label":"Style and color","data_type":"text","options":null,"required":false,"promote":true},{"object_type":"selection","job_type_key":null,"field_key":"dye_lot","label":"Dye lot or shade lot","data_type":"text","options":null,"required":true,"promote":true},{"object_type":"selection","job_type_key":null,"field_key":"roll_number","label":"Roll number","data_type":"text","options":null,"required":false,"promote":false},{"object_type":"selection","job_type_key":null,"field_key":"quantity_sf","label":"Quantity (SF)","data_type":"number","options":null,"required":false,"promote":true},{"object_type":"selection","job_type_key":null,"field_key":"waste_pct","label":"Planned waste","data_type":"number","options":null,"required":false,"promote":false},{"object_type":"selection","job_type_key":null,"field_key":"room","label":"Room","data_type":"text","options":null,"required":false,"promote":false},{"object_type":"project","job_type_key":null,"field_key":"measured_sf","label":"Measured square feet","data_type":"number","options":null,"required":false,"promote":true},{"object_type":"project","job_type_key":null,"field_key":"salesperson","label":"Salesperson","data_type":"text","options":null,"required":false,"promote":true},{"object_type":"project","job_type_key":null,"field_key":"tax_mode","label":"Sales tax treatment","data_type":"enum","options":["retail_sale","contractor_improvement","exempt_resale"],"required":false,"promote":true},{"object_type":"project","job_type_key":null,"field_key":"subfloor","label":"Subfloor","data_type":"enum","options":["plywood","osb","concrete","existing_tile","other"],"required":false,"promote":false},{"object_type":"project","job_type_key":"builder_lot","field_key":"lot_number","label":"Lot number","data_type":"text","options":null,"required":false,"promote":false},{"object_type":"work_order","job_type_key":null,"field_key":"installer_pay_cents","label":"Installer pay","data_type":"money_cents","options":null,"required":false,"promote":true}],"price_book":[{"code":"L-CPT","name":"Carpet install","unit":"SY","price_cents":850,"cost_cents":550,"labor_minutes":null,"cost_code":"LAB-CPT"},{"code":"L-PAD","name":"Pad install","unit":"SY","price_cents":150,"cost_cents":100,"labor_minutes":null,"cost_code":"LAB-CPT"},{"code":"L-LVP-FLT","name":"LVP or laminate, floating","unit":"SF","price_cents":250,"cost_cents":160,"labor_minutes":null,"cost_code":"LAB-HS"},{"code":"L-LVP-GLU","name":"LVP glue-down","unit":"SF","price_cents":325,"cost_cents":210,"labor_minutes":null,"cost_code":"LAB-HS"},{"code":"L-HWD-NAIL","name":"Solid hardwood, nail-down","unit":"SF","price_cents":450,"cost_cents":300,"labor_minutes":null,"cost_code":"LAB-HS"},{"code":"L-HWD-GLU","name":"Engineered hardwood, glue-down","unit":"SF","price_cents":500,"cost_cents":325,"labor_minutes":null,"cost_code":"LAB-HS"},{"code":"L-TILE","name":"Floor tile install","unit":"SF","price_cents":900,"cost_cents":600,"labor_minutes":null,"cost_code":"LAB-TIL"},{"code":"L-PREP","name":"Floor prep and leveling","unit":"HR","price_cents":7500,"cost_cents":4500,"labor_minutes":60,"cost_code":"LAB-PREP"},{"code":"L-REM-CPT","name":"Remove carpet and pad","unit":"SY","price_cents":200,"cost_cents":125,"labor_minutes":null,"cost_code":"LAB-REM"},{"code":"L-REM-HS","name":"Remove hard surface","unit":"SF","price_cents":150,"cost_cents":100,"labor_minutes":null,"cost_code":"LAB-REM"},{"code":"L-STAIR","name":"Stairs","unit":"STEP","price_cents":1500,"cost_cents":1000,"labor_minutes":null,"cost_code":"LAB-STR"},{"code":"L-BASE","name":"Base or quarter round","unit":"LF","price_cents":250,"cost_cents":150,"labor_minutes":null,"cost_code":"LAB-HS"},{"code":"L-MOVE","name":"Furniture moving","unit":"ROOM","price_cents":3500,"cost_cents":2000,"labor_minutes":null,"cost_code":"LAB-MOV"},{"code":"L-TRANS","name":"Transition strip","unit":"EA","price_cents":2500,"cost_cents":1500,"labor_minutes":null,"cost_code":"LAB-HS"}],"kpis":[{"key":"margin","label":"Gross margin by order","metric":"gross_margin_pct","good_direction":"up"},{"key":"material_margin","label":"Material margin","metric":"material_margin_pct","good_direction":"up"},{"key":"labor_margin","label":"Labor margin","metric":"labor_margin_pct","good_direction":"up"},{"key":"waste","label":"Waste over estimate","metric":"waste_variance_pct","good_direction":"down"},{"key":"callbacks","label":"Callbacks","metric":"callback_rate_pct","good_direction":"down"},{"key":"install_rate","label":"SF installed per crew day","metric":"installer_sqft_per_day","good_direction":"up"},{"key":"unbilled","label":"Installed, balance not billed","metric":"completed_unbilled_cents","good_direction":"down"},{"key":"close_rate","label":"Quote close rate","metric":"close_rate_pct","good_direction":"up"}],"books_proposal":{"cost_type_roles":{"LABOR":"DIRECT_LABOR_COST","MATERIALS":"MATERIALS_COST","SUBCONTRACTOR":"SUBCONTRACT_COST","OTHER":"OTHER_JOB_COST"},"rev_rec_by_job_type":{"retail_install":"POINT_IN_TIME","builder_lot":"POINT_IN_TIME","commercial_flooring":"PCT_COMPLETE"}},"sample_job":null,"plan_hash":"543bc454edb3761bb3839f605fccd4d9f51619b4f98253a7283182b539853407"}$plan$::jsonb;
  v_admin       text;     -- Clerk user id of the company_admin we run as (never printed)
  v_admin_emp   uuid;
  v_admin_label text;
  v_tech        uuid;     -- an existing active core.employees row used as the field tech / installer
  v_tech_label  text;
  v_pack        text;
  v_install     uuid;
  v_applied     boolean := false;
  v_job uuid; v_key text; v_est uuid; v_est2 uuid; v_j jsonb; v_budget uuid; v_sov uuid; v_bill uuid;
  v_cmt uuid; v_cmt2 uuid; v_doc uuid; v_co uuid; v_wo uuid; v_wo2 uuid; v_res jsonb; v_sel uuid; v_sel2 uuid;
  v_opt uuid; v_item uuid; v_meas uuid; v_asset uuid; v_agr uuid; v_card uuid; v_card2 uuid; v_stock uuid;
  v_fail text[]; v_n int; v_amt bigint;
  v_thu date := current_date + ((10 - extract(isodow from current_date)::int) % 7) + 1;   -- next Thursday (1–7 days out)
  v_tue date := current_date + ((8 - extract(isodow from current_date)::int) % 7) + 1;    -- next Tuesday (1–7 days out)
  v_period_end date := case when extract(day from current_date) <= 25
                            then date_trunc('month', current_date)::date + 24
                            else (date_trunc('month', current_date) + interval '1 month')::date + 24 end;  -- pay-app cutoff (25th)
  n_jobs int := 0; n_cust int := 0; n_vend int := 0;
  v_c_kowalski uuid;
  v_c_nguyen uuid;
  v_c_prairietrail uuid;
  v_c_thompson uuid;
  v_c_schmidt uuid;
  v_c_waukee uuid;
  v_v_heartland uuid;
  v_v_midlands uuid;
  v_v_jensen uuid;

begin
  -- ---- 0. who we run as (read-only lookups as the migration owner; nothing is written here) ----
  select e.clerk_user_id, e.id, e.role || ' ' || e.first_name || ' ' || e.last_name
    into v_admin, v_admin_emp, v_admin_label
    from core.employees e
   where e.org_id = c_org and e.role = 'company_admin' and e.is_active and e.clerk_user_id is not null
   order by e.created_at, e.id limit 1;
  if v_admin is null then
    raise exception 'DEMO: org % has no active company_admin with a Clerk user id; nothing seeded', c_org;
  end if;
  -- field tech: an existing active employee other than the admin (Core owns employees; never inserted here)
  select e.id, e.role || ' ' || e.first_name || ' ' || e.last_name into v_tech, v_tech_label
    from core.employees e
   where e.org_id = c_org and e.is_active and e.id <> v_admin_emp
   order by (lower(e.first_name || ' ' || e.last_name) ~ '(install|tech|service)') desc, e.created_at, e.id limit 1;
  if v_tech is null then v_tech := v_admin_emp; v_tech_label := v_admin_label || ' (only employee)'; end if;
  -- existing demo parties (reused by name so a rerun calls no RPC and writes no activity)
  select c.id into v_c_kowalski from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Sara & Jake Kowalski')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_nguyen from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Minh & Lan Nguyen')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_prairietrail from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Prairie Trail Homes')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_thompson from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Rachel Thompson')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_schmidt from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Dale & Karen Schmidt')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select c.id into v_c_waukee from core.customers c
   where c.org_id = c_org and c.deleted_at is null and lower(regexp_replace(btrim(c.name), '\s+', ' ', 'g')) = lower('Demo — Waukee Community School District')
   order by c.is_active desc, c.created_at, c.id limit 1;
  select v.id into v_v_heartland from core.vendors v
   where v.org_id = c_org and v.deleted_at is null and lower(regexp_replace(btrim(v.name), '\s+', ' ', 'g')) = lower('Demo — Heartland Floor Distributors')
   order by v.is_active desc, v.created_at, v.id limit 1;
  select v.id into v_v_midlands from core.vendors v
   where v.org_id = c_org and v.deleted_at is null and lower(regexp_replace(btrim(v.name), '\s+', ' ', 'g')) = lower('Demo — Midlands Carpet Mills')
   order by v.is_active desc, v.created_at, v.id limit 1;
  select v.id into v_v_jensen from core.vendors v
   where v.org_id = c_org and v.deleted_at is null and lower(regexp_replace(btrim(v.name), '\s+', ' ', 'g')) = lower('Demo — Jensen Install Co.')
   order by v.is_active desc, v.created_at, v.id limit 1;

  -- ---- 1. become the company_admin ----
  perform set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  set local role authenticated;
  if public.get_org_id() is distinct from c_org then
    raise exception 'DEMO: the company_admin does not resolve to org % (active in more than one org?)', c_org;
  end if;

  -- ---- 2. pack ----
  select i.pack_key into v_pack from pm.pack_installs i
   where i.location_id = c_loc and i.role = 'primary' and i.status = 'ACTIVE';
  if v_pack is null then
