  end if;

  -- ------------------------------------------------------------------------
  -- chf-thompson-basement: SAMPLE — measure and quote, measure in the dispatch queue (unassigned)
  -- ------------------------------------------------------------------------
  v_key := 'chf-thompson-basement';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'retail_install', 'Thompson — basement carpet and stairs', v_c_thompson, null, true,
      jsonb_build_object('_demo', v_key, 'salesperson', 'Showroom (Mike H.)', 'tax_mode', 'retail_sale', 'subfloor', 'concrete'));
    update pm.projects set site_address_line1 = '412 8th St SW', site_city = 'Altoona', site_state = 'IA', site_zip = '50009',
           planned_start = null, planned_finish = null,
           pm_user_id = v_admin
     where job_id = v_job;
    insert into pm.estimates (job_id, title, retainage_pct, valid_until, notes)
      values (v_job, 'Draft quote — basement carpet (pending measure)', null, current_date + 30, null) returning id into v_est;
    insert into pm.estimate_lines (estimate_id, line_no, sort, cost_code_id, description, qty, uom, unit_cost_cents, unit_price_cents, cost_cents, amount_cents, is_allowance)
    select v_est, x.n, x.n, c.id, x.d, x.qty::numeric, x.uom, x.uc::bigint, x.up::bigint, x.cost::bigint, x.amt::bigint, x.allow
      from (values
      (1, 'MAT-CPT', 'Basement carpet, solution-dyed nylon (48 SY)', 48, 'SY', 1950, 3290, 93600, 157920, false),
      (2, 'MAT-PAD', '8 lb rebond pad with moisture barrier', 48, 'SY', 480, 790, 23040, 37920, false),
      (3, 'LAB-CPT', 'Carpet install', 48, 'SY', 550, 850, 26400, 40800, false),
      (4, 'LAB-STR', 'Stairs (13 steps)', 13, 'STEP', 1000, 1500, 13000, 19500, false)) x(n, code, d, qty, uom, uc, up, cost, amt, allow)
      left join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 4 or exists (select 1 from pm.estimate_lines l where l.estimate_id = v_est and l.cost_code_id is null and l.cost_cents <> 0) then
      raise exception 'DEMO %: estimate lines did not resolve their cost codes', v_key;
    end if;
    v_wo := pm.create_work_order(p_job => v_job, p_kind => 'MEASURE', p_summary => 'Measure basement family room and stairs', p_priority => 3,
      p_requested_start => ((current_date + 1) + time '13:00') at time zone 'America/Chicago', p_requested_end => ((current_date + 1) + time '15:00') at time zone 'America/Chicago', p_estimated_minutes => 45);
    insert into pm.tasks (job_id, title, status, is_milestone, start_on, due_on, duration_days, pct_complete, sort, completed_at, assignee_user_id, assignee_employee_id)
    select v_job, x.t, x.st, x.ms, current_date + x.s, current_date + x.d, x.d - x.s, x.pct::numeric, x.n,
           case when x.st = 'DONE' then now() end, case when x.who = 'admin' then v_admin end, case when x.who = 'tech' then v_tech end
      from (values
      (1, 'Measure appointment (needs an estimator)', 'TODO', false, 1, 1, null, null)) x(n, t, st, ms, s, d, pct, who);
    n_jobs := n_jobs + 1;
  end if;

  -- ------------------------------------------------------------------------
  -- chf-schmidt-kitchen-tile: SAMPLE — installed, balance invoice drafted
  -- ------------------------------------------------------------------------
  v_key := 'chf-schmidt-kitchen-tile';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'retail_install', 'Schmidt — kitchen and laundry tile', v_c_schmidt, null, true,
      jsonb_build_object('_demo', v_key, 'measured_sf', 190, 'salesperson', 'Showroom (Mike H.)', 'tax_mode', 'retail_sale', 'subfloor', 'plywood'));
    update pm.projects set site_address_line1 = '6120 NW 62nd Ave', site_city = 'Johnston', site_state = 'IA', site_zip = '50131',
           planned_start = current_date + -6, planned_finish = current_date + -6,
           pm_user_id = v_admin
     where job_id = v_job;
    insert into pm.estimates (job_id, title, retainage_pct, valid_until, notes)
      values (v_job, 'Quote — kitchen and laundry tile', null, current_date - 10, null) returning id into v_est;
    insert into pm.estimate_lines (estimate_id, line_no, sort, cost_code_id, description, qty, uom, unit_cost_cents, unit_price_cents, cost_cents, amount_cents, is_allowance)
    select v_est, x.n, x.n, c.id, x.d, x.qty::numeric, x.uom, x.uc::bigint, x.up::bigint, x.cost::bigint, x.amt::bigint, x.allow
      from (values
      (1, 'MAT-TIL', 'Porcelain 24x24, Ash (210 SF incl. waste)', 210, 'SF', 340, 580, 71400, 121800, false),
      (2, 'MAT-SUN', 'Thinset, grout and uncoupling membrane', 1, 'EA', 18600, 29800, 18600, 29800, false),
      (3, 'MAT-TRN', 'Schluter edge trim', 6, 'EA', 1800, 3200, 10800, 19200, false),
      (4, 'LAB-TIL', 'Floor tile install', 190, 'SF', 600, 900, 114000, 171000, false),
      (5, 'LAB-REM', 'Remove sheet vinyl and underlayment', 190, 'SF', 100, 150, 19000, 28500, false)) x(n, code, d, qty, uom, uc, up, cost, amt, allow)
      left join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 5 or exists (select 1 from pm.estimate_lines l where l.estimate_id = v_est and l.cost_code_id is null and l.cost_cents <> 0) then
      raise exception 'DEMO %: estimate lines did not resolve their cost codes', v_key;
    end if;
    perform pm.send_estimate(v_est);
    v_j := pm.accept_estimate(v_est);
    perform pm.request_deposit(v_job, 185150, 'Deposit — 50% at signing');
    insert into pm.selections (job_id, category, title, due_on, ext)
      values (v_job, 'Tile', 'Kitchen and laundry floor tile', current_date - 25,
              jsonb_build_object('style_color', 'Ash 24x24', 'dye_lot', 'ASH-0826-3', 'room', 'Kitchen and laundry', 'quantity_sf', 210, 'waste_pct', 0.1))
      returning id into v_sel;
    insert into pm.selection_options (selection_id, sort, label, vendor_id, vendor_sku, qty, uom, unit_cost_cents, unit_price_cents, lead_time_days, is_recommended)
      values (v_sel, 1, 'Porcelain 24x24, Ash', v_v_heartland, 'HFD-P2424-ASH', 210, 'SF', 340, 580, 5, true) returning id into v_opt;
    perform pm.approve_selection(v_sel, v_opt, 'Demo Client', 'IN_PERSON');
    v_fail := pm.transition_stage(v_job, 'sold');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'sold', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'ordered');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'ordered', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'received');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'received', v_fail; end if;
    v_fail := pm.transition_stage(v_job, 'installing');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'installing', v_fail; end if;
    v_wo := pm.create_work_order(p_job => v_job, p_kind => 'INSTALL', p_summary => 'Install kitchen and laundry tile (190 SF)', p_priority => 3,
      p_requested_start => ((current_date - 6) + time '08:00') at time zone 'America/Chicago', p_requested_end => ((current_date - 6) + time '16:00') at time zone 'America/Chicago', p_estimated_minutes => 480,
      p_ext => jsonb_build_object('installer_pay_cents', 114000));
    perform pm.schedule_work_order(v_wo, ((current_date - 6) + time '08:00') at time zone 'America/Chicago', ((current_date - 6) + time '16:00') at time zone 'America/Chicago', array[v_tech]);
    perform pm.complete_work_order(v_wo, 'COMPLETED', 'Installed 190 SF on uncoupling membrane; grouted, sealed, laundry threshold trimmed.');
    v_fail := pm.transition_stage(v_job, 'installed');
    if cardinality(v_fail) > 0 then raise exception 'DEMO %: move to % blocked by guards %', v_key, 'installed', v_fail; end if;
    insert into pm.time_entries (job_id, employee_id, work_date, hours, pay_type, cost_code_id, notes, approval_state, work_order_id)
    select v_job, v_tech, current_date + x.day, x.h::numeric, x.pay, c.id, x.notes, 'SUBMITTED', x.wo::uuid
      from (values
      (-6, 7, 'REG', 'LAB-W2', 'Helper: demo sheet vinyl, set membrane, grout', v_wo::text)) x(day, h, pay, code, notes, wo)
      join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    insert into pm.billing_requests (job_id, billing_type, billing_subtype, occurred_on, memo)
      values (v_job, 'MILESTONE', 'FIXED', current_date, 'Balance on completion (the deposit is applied in Books)') returning id into v_bill;
    insert into pm.billing_request_lines (billing_request_id, line_no, sort, description, amount_cents)
      values (v_bill, 1, 1, 'Tile, setting materials and trim', 170800),
             (v_bill, 2, 2, 'Installation and removal of existing floor', 199500);
    n_jobs := n_jobs + 1;
  end if;

  -- ------------------------------------------------------------------------
  -- chf-waukee-csd-corridor: SAMPLE — commercial bid sent (pay-app job type)
  -- ------------------------------------------------------------------------
  v_key := 'chf-waukee-csd-corridor';
  select p.job_id into v_job from pm.projects p where p.location_id = c_loc and p.ext ->> '_demo' = v_key;
  if v_job is null then

    v_job := pm.create_project(c_loc, 'commercial_flooring', 'Waukee CSD — Prairieview corridor LVT replacement', v_c_waukee, null, true,
      jsonb_build_object('_demo', v_key, 'measured_sf', 8400, 'tax_mode', 'exempt_resale', 'subfloor', 'concrete', 'customer_reference', 'Bid 2027-04'));
    update pm.projects set site_address_line1 = '755 SE Alice Nelson Dr', site_city = 'Waukee', site_state = 'IA', site_zip = '50263',
           planned_start = current_date + 240, planned_finish = current_date + 255,
           pm_user_id = v_admin
     where job_id = v_job;
    insert into pm.estimates (job_id, title, retainage_pct, valid_until, notes)
      values (v_job, 'Bid — corridor LVT replacement (summer 2027)', 0.05, current_date + 45, 'Work during summer break only. Moisture testing by others.') returning id into v_est;
    insert into pm.estimate_lines (estimate_id, line_no, sort, cost_code_id, description, qty, uom, unit_cost_cents, unit_price_cents, cost_cents, amount_cents, is_allowance)
    select v_est, x.n, x.n, c.id, x.d, x.qty::numeric, x.uom, x.uc::bigint, x.up::bigint, x.cost::bigint, x.amt::bigint, x.allow
      from (values
      (1, 'MAT-LVP', 'Commercial LVT 18x18, 28 mil wear', 8400, 'SF', 310, 495, 2604000, 4158000, false),
      (2, 'LAB-REM', 'Remove VCT and scrape', 8400, 'SF', 100, 150, 840000, 1260000, false),
      (3, 'LAB-PREP', 'Floor prep and leveling', 40, 'HR', 4500, 7500, 180000, 300000, false),
      (4, 'LAB-HS', 'LVT glue-down install', 8400, 'SF', 210, 325, 1764000, 2730000, false),
      (5, 'MAT-TRN', 'Rubber base, 4 in', 1900, 'LF', 120, 240, 228000, 456000, false)) x(n, code, d, qty, uom, uc, up, cost, amt, allow)
      left join pm.cost_codes c on c.location_id = c_loc and c.job_id is null and c.code = x.code;
    get diagnostics v_n = row_count;
    if v_n <> 5 or exists (select 1 from pm.estimate_lines l where l.estimate_id = v_est and l.cost_code_id is null and l.cost_cents <> 0) then
      raise exception 'DEMO %: estimate lines did not resolve their cost codes', v_key;
    end if;
    perform pm.send_estimate(v_est);
    insert into pm.tasks (job_id, title, status, is_milestone, start_on, due_on, duration_days, pct_complete, sort, completed_at, assignee_user_id, assignee_employee_id)
    select v_job, x.t, x.st, x.ms, current_date + x.s, current_date + x.d, x.d - x.s, x.pct::numeric, x.n,
           case when x.st = 'DONE' then now() end, case when x.who = 'admin' then v_admin end, case when x.who = 'tech' then v_tech end
      from (values
      (1, 'Bid due to district facilities', 'TODO', true, 9, 9, null, 'admin')) x(n, t, st, ms, s, d, pct, who);
    n_jobs := n_jobs + 1;
  end if;


  -- ---- 6. summary ----
  raise notice 'DEMO CHF: ran as %; field tech %; pack % (%); this run created % job(s), % customer(s), % vendor(s)',
    v_admin_label, v_tech_label, c_pack, case when v_applied then 'applied now' else 'already installed' end, n_jobs, n_cust, n_vend;
  raise notice 'DEMO CHF totals: % demo jobs (% sample, % real); % tasks; % budget lines; % estimates (% accepted); % change orders; % commitments; % work orders (% dispatched); % billing requests; % deposit requests; % selections; % assets; % agreements; % time entries; % daily logs; % Books events from demo jobs',
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo' and p.is_sample),
    (select count(*) from pm.projects p where p.location_id = c_loc and p.ext ? '_demo' and not p.is_sample),
    (select count(*) from pm.tasks t join pm.projects p on p.job_id = t.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.budget_lines l join pm.budgets b on b.id = l.budget_id join pm.projects p on p.job_id = b.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.estimates e where e.location_id = c_loc),
    (select count(*) from pm.estimates e where e.location_id = c_loc and e.status = 'ACCEPTED'),
    (select count(*) from pm.change_orders x join pm.projects p on p.job_id = x.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.commitments x where x.location_id = c_loc),
    (select count(*) from pm.work_orders w where w.location_id = c_loc),
    (select count(distinct d.work_order_id) from pm.dispatch_assignments d join pm.work_orders w on w.id = d.work_order_id where w.location_id = c_loc and d.status <> 'CANCELLED'),
    (select count(*) from pm.billing_requests r where r.location_id = c_loc),
    (select count(*) from pm.deposit_requests r where r.location_id = c_loc),
    (select count(*) from pm.selections s join pm.projects p on p.job_id = s.job_id where p.location_id = c_loc),
    (select count(*) from pm.assets a where a.location_id = c_loc),
    (select count(*) from pm.service_agreements a where a.location_id = c_loc),
    (select count(*) from pm.time_entries t join pm.projects p on p.job_id = t.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from pm.field_logs l join pm.projects p on p.job_id = l.job_id where p.location_id = c_loc and p.ext ? '_demo'),
    (select count(*) from core.events e where e.org_id = c_org and e.source_module = 'PROJECTS'
        and e.payload ->> 'job_id' in (select p.job_id::text from pm.projects p where p.location_id = c_loc and p.ext ? '_demo'));
end
$seed$;
